from heapq import heappush, heappop

def solve():
	(n, D) = map(int, input().split())
	data = {}
	heap = []
	for i in range(n):
		(d, t, s) = map(int, input().split())
		if d in data:
			data[d].append([t, s])
		else:
			data[d] = [[t, s]]
	for d in range(1, D + 1):
		if d in data:
			for v in data[d]:
				heappush(heap, [-1 * v[1], v[0]])
		if len(heap):
			x = heappop(heap)
			x[1] -= 1
			if x[1]:
				heappush(heap, x)
	ans = 0
	while len(heap):
		x = heappop(heap)
		ans += -1 * x[0] * x[1]
	return ans
for _ in range(int(input())):
	print(solve())
